import {readFile,writeFile} from 'node:fs/promises';
// Bundle fixed, trusted modules as source at build time. No runtime eval or filesystem.
const files=['art.js','wear-data.js','catalog.js','bouquet.js','gift-schema.js','gift-pricing.js'];
const sources=await Promise.all(files.map(name=>readFile(new URL('../dist/'+name,import.meta.url),'utf8')));
await writeFile(new URL('../lib/generated-schema.mjs',import.meta.url),
 '// Generated by scripts/build-schema.mjs. Do not edit.\nconst window={};\n'+sources.join('\n')+'\nexport const schema=window.GiftSchema;\nexport const products=window.LoveCatalog.products;\nexport const pricing=window.GiftPricing;\n');
